#pragma once
#include "../worlded/src/world_update_export.hpp"
#include <sstream>
// Housing keeps purchase/role metadata; physical changes use the world-update ABI.
inline worlded::Bytes housing_update_template(const worlded::Installation& game,const std::string& map,unsigned sx,unsigned sy,const std::map<std::string,worlded::Bytes>& files){
    using namespace worlded;auto baseline=read_world_sector(game,map,sx,sy);Building scene{BuildingPlan{},baseline.sector,{}, {}};scene.map_name=map;scene.sector_id=std::uint64_t(sx)|(std::uint64_t(sy)<<26);scene.existing_map=true;
    auto hash=reference_hash(game.read(baseline.source));auto sourceObjects=sector_objects(baseline.sector);UpdateReview review;review.package="housing.template";review.version="1.0.0";review.revision=1;
    auto rows=[&](const std::string& name){auto it=files.find(name);return it==files.end()?std::vector<Message>{}:read_messages(it->second);};
    auto append=[&](QJsonObject operation,const std::string& id){operation["id"]=QString::fromStdString(id);review.operations.append(operation);};
    for(const auto& [path,bytes]:files)if(path.rfind("objects/",0)==0){auto objects=read_objects(bytes);if(objects.size()!=1 || encode_instance(objects[0])!=bytes)throw std::runtime_error("Housing payload fails MOB roundtrip: "+path);auto object=objects[0];if(object.id.substr(0,4)!="0200" || object.type>17 || object.type==4 || object.type==15)throw std::runtime_error("Invalid housing update object");SceneOrigin origin;origin.mobile=true;origin.object=object;auto op=updateOperation(scene,"add_object",1,&origin);op["payload"]=QString::fromStdString(path);append(op,"add-"+object.id);review.resources[path]=bytes;}
    for(const auto& [path,bytes]:files)if(path.rfind("resources/",0)==0)review.resources[path.substr(10)]=bytes;
    auto cells=[&](const std::string& file,const QString& kind,unsigned width){for(const auto& row:rows(file)){if(row.id>=width*width)throw std::runtime_error("Housing cell is outside sector");std::istringstream input(row.text);std::uint64_t after;std::string extra;if(!(input>>after) || input>>extra || after>UINT32_MAX)throw std::runtime_error("Invalid housing cell value");auto before=kind=="set_ground"?baseline.sector.tile(row.id%width,row.id/width):kind=="set_roof"?baseline.sector.roof(row.id%width,row.id/width):std::uint32_t(baseline.sector.blocked(row.id%width,row.id/width));if(kind=="set_block" && after>1)throw std::runtime_error("Invalid blocking value");if(before==after)continue;auto op=updateOperation(scene,kind,1);auto selector=op["selector"].toObject();selector["base_path"]=QString::fromStdString(baseline.source);selector["base_sha256"]=QString::fromStdString(hash);op["selector"]=selector;op["index"]=int(row.id);op["before"]=updateValues(before);op["after"]=updateValues(after);append(op,kind.toStdString()+"-"+std::to_string(row.id));}};
    cells("terrain.mes","set_ground",64);cells("roofs.mes","set_roof",16);cells("blocking.mes","set_block",64);
    auto global=[&](const GameObject& object){auto loc=object.number("LOCATION");return baseline.generated?std::uint64_t(sx*64+(loc&63))|((std::uint64_t(sy*64)+((loc>>32)&63))<<32):loc;};
    std::set<unsigned> hidden;
    for(const auto& row:rows("removed.mes")){std::istringstream input(row.text);std::uint64_t loc,aid;std::int32_t dx,dy;std::string extra;if(!(input>>loc>>aid>>dx>>dy) || input>>extra)throw std::runtime_error("Invalid housing removal selector");std::vector<unsigned> matches;for(unsigned i=0;i<sourceObjects.size();i++){auto& o=sourceObjects[i];if(global(o)==loc && o.number("CURRENT_AID")==aid && std::int32_t(o.number("OFFSET_X"))==dx && std::int32_t(o.number("OFFSET_Y"))==dy)matches.push_back(i);}if(matches.size()!=1)throw std::runtime_error("Housing removal selector has no unique original record");if(sourceObjects[matches[0]].type!=3)throw std::runtime_error("Only original scenery can be hidden by a housing update");hidden.insert(matches[0]);}
    for(const auto& row:rows("vegetation.mes")){std::istringstream input(row.text);unsigned mask;if(row.id>=4096 || !(input>>mask))throw std::runtime_error("Invalid vegetation clearance rule");mask&=0x3e;for(unsigned i=0;i<sourceObjects.size();i++){auto& o=sourceObjects[i];auto loc=global(o),aid=o.number("CURRENT_AID");unsigned kind=(aid>>28)==4?unsigned((aid>>6)&31):0;if(o.type==3 && (loc&63)==row.id%64 && ((loc>>32)&63)==row.id/64 && (mask&(1u<<kind)))hidden.insert(i);}}
    for(auto i:hidden){const auto& object=sourceObjects[i];SceneOrigin origin;origin.source_path=baseline.source;origin.source_hash=hash;origin.ordinal=i;origin.object=object;auto op=updateOperation(scene,"hide_scenery",1,&origin);op["before"]=updateValues(object.number("FLAGS")&2);op["after"]=updateValues(2);append(op,"hide-"+std::to_string(i));}
    auto manifest=updateManifest(review);QJsonObject sourceHashes;for(const auto& [name,data]:files)if(name!="update-template.json")sourceHashes[QString::fromStdString(name)]=QString::fromStdString(reference_hash(data));manifest["housing_source_hashes"]=sourceHashes;encodeUpdatePackage(manifest);auto json=QJsonDocument(manifest).toJson();return Bytes(json.begin(),json.end());
}

inline worlded::Bytes housing_update_revision(const worlded::Bytes& fresh,std::map<std::string,worlded::Bytes>& files,const std::filesystem::path& previous){
    using namespace worlded;auto json=[](const Bytes& bytes){auto doc=QJsonDocument::fromJson(QByteArray(reinterpret_cast<const char*>(bytes.data()),int(bytes.size())));if(!doc.isObject())throw std::runtime_error("Invalid housing update template");return doc.object();};auto next=json(fresh),old=json(read_file(previous/"update-template.json"));encodeUpdatePackage(old);auto current=next["operations"].toArray(),desired=old.value("housing_desired_operations").toArray();if(desired.isEmpty() && old["revision"].toInt()==1)desired=old["operations"].toArray();if(desired.isEmpty() && !old["operations"].toArray().isEmpty())throw std::runtime_error("Previous housing template has no authored checkpoint");auto revision=old["revision"].toInt()+1;QMap<QString,QJsonObject> remaining;for(auto value:desired)remaining[value.toObject()["id"].toString()]=value.toObject();auto history=old["operations"].toArray();bool changed=false;
    auto append=[&](QJsonObject op){op["id"]=op["id"].toString()+"-r"+QString::number(revision);op["revision"]=revision;history.append(op);changed=true;};
    for(auto value:current){auto op=value.toObject(),before=remaining.take(op["id"].toString());if(before.isEmpty()){append(op);continue;}auto normalized=op;normalized["after"]=before["after"];if(normalized!=before)throw std::runtime_error("Housing reference or existing object changed; use an explicit reviewed migration");if(op["after"]!=before["after"]){op["before"]=before["after"];append(op);}}
    for(auto before:remaining){auto kind=before["kind"].toString();if(kind!="set_ground" && kind!="set_roof" && kind!="set_block")throw std::runtime_error("Removing a previously published housing object/clearance requires an explicit migration");QJsonValue target=before["before"];before["before"]=before["after"];before["after"]=target;append(before);}
    QMap<QString,QJsonObject> resources;for(auto value:old["resources"].toArray()){auto entry=value.toObject();auto path=entry["path"].toString().toStdString();auto file=path.rfind("objects/",0)==0?path:"resources/"+path;auto data=read_file(previous/file);if(reference_hash(data)!=entry["sha256"].toString().toStdString())throw std::runtime_error("Previous housing resource hash changed");if(files.count(file) && files.at(file)!=data)throw std::runtime_error("A published housing resource is immutable");files[file]=std::move(data);resources[entry["path"].toString()]=entry;}
    for(auto value:next["resources"].toArray()){auto entry=value.toObject();if(!resources.contains(entry["path"].toString()))changed=true;resources[entry["path"].toString()]=entry;}QJsonArray all;for(auto value:resources)all.append(value);next["resources"]=all;next["operations"]=history;next["revision"]=changed?revision:old["revision"].toInt();next["package_id"]=old["package_id"];next["housing_desired_operations"]=current;encodeUpdatePackage(next);auto data=QJsonDocument(next).toJson();return Bytes(data.begin(),data.end());
}
